// Gather data from all sources
const weekBounds = $('Set: Week Boundaries').first().json;
const tradesData = $('HTTP: Fetch Week Trade Grades').first()?.json || {};
const jiraData = $('HTTP: Fetch LEARN Jira Tickets').first()?.json || {};
const patternsData = $('HTTP: Fetch Pattern Detections').first()?.json || {};
const hypothesesData = $('HTTP: Fetch Hypotheses Status').first()?.json || {};
const previousLessons = $('HTTP: Fetch Previous Lessons').first()?.json?.lessons || [];

const trades = tradesData.trades || [];
const jiraIssues = jiraData.issues || [];
const patterns = patternsData.patterns || [];
const hypotheses = hypothesesData.hypotheses || [];

// Initialize aggregations
const aggregations = {
  byStrategy: {},
  byPatternType: {},
  byTimeOfDay: {
    premarket: { trades: [], avgGrade: 0, totalPnL: 0 },
    opening: { trades: [], avgGrade: 0, totalPnL: 0 },
    midday: { trades: [], avgGrade: 0, totalPnL: 0 },
    closing: { trades: [], avgGrade: 0, totalPnL: 0 },
    afterhours: { trades: [], avgGrade: 0, totalPnL: 0 }
  },
  byAssetClass: {
    crypto: { trades: [], avgGrade: 0, totalPnL: 0, winRate: 0 },
    forex: { trades: [], avgGrade: 0, totalPnL: 0, winRate: 0 },
    options: { trades: [], avgGrade: 0, totalPnL: 0, winRate: 0 },
    futures: { trades: [], avgGrade: 0, totalPnL: 0, winRate: 0 },
    equity: { trades: [], avgGrade: 0, totalPnL: 0, winRate: 0 }
  },
  byGrade: { A: [], B: [], C: [], D: [], F: [] },
  byWeakness: {},
  byLesson: {}
};

// Grade to numeric score mapping
const gradeToScore = { 'A': 95, 'A-': 90, 'B+': 87, 'B': 83, 'B-': 80, 'C+': 77, 'C': 73, 'C-': 70, 'D': 60, 'F': 40 };

// Categorize asset class from symbol
function getAssetClass(symbol) {
  if (!symbol) return 'equity';
  const sym = symbol.toUpperCase();
  if (sym.includes('BTC') || sym.includes('ETH') || sym.includes('SOL') || sym.includes('USDT')) return 'crypto';
  if (sym.includes('USD') || sym.includes('EUR') || sym.includes('GBP') || sym.includes('JPY') || sym.includes('CHF')) return 'forex';
  if (sym.includes('SPY') || sym.includes('SPX') || sym.includes('0DTE') || /\d{6}[CP]/.test(sym)) return 'options';
  if (sym.includes('ES') || sym.includes('NQ') || sym.includes('MES') || sym.includes('MNQ') || sym.includes('/')) return 'futures';
  return 'equity';
}

// Get time of day category
function getTimeCategory(timestamp) {
  if (!timestamp) return 'midday';
  const hour = new Date(timestamp).getHours();
  if (hour < 9 || (hour === 9 && new Date(timestamp).getMinutes() < 30)) return 'premarket';
  if (hour < 11) return 'opening';
  if (hour < 14) return 'midday';
  if (hour < 16) return 'closing';
  return 'afterhours';
}

// Process trades
trades.forEach(trade => {
  const strategy = trade.strategy || 'unknown';
  const assetClass = getAssetClass(trade.symbol);
  const timeCategory = getTimeCategory(trade.entry_time);
  const gradeKey = trade.grade?.charAt(0) || 'C';
  const gradeScore = gradeToScore[trade.grade] || gradeToScore[gradeKey] || 73;
  const pnl = parseFloat(trade.pnl) || 0;

  // By Strategy
  if (!aggregations.byStrategy[strategy]) {
    aggregations.byStrategy[strategy] = { trades: [], grades: [], totalPnL: 0, lessons: [], weaknesses: [] };
  }
  aggregations.byStrategy[strategy].trades.push(trade);
  aggregations.byStrategy[strategy].grades.push(gradeScore);
  aggregations.byStrategy[strategy].totalPnL += pnl;
  if (trade.lessons) aggregations.byStrategy[strategy].lessons.push(...(Array.isArray(trade.lessons) ? trade.lessons : [trade.lessons]));
  if (trade.weaknesses) aggregations.byStrategy[strategy].weaknesses.push(...(Array.isArray(trade.weaknesses) ? trade.weaknesses : [trade.weaknesses]));

  // By Time of Day
  aggregations.byTimeOfDay[timeCategory].trades.push(trade);
  aggregations.byTimeOfDay[timeCategory].totalPnL += pnl;

  // By Asset Class
  aggregations.byAssetClass[assetClass].trades.push(trade);
  aggregations.byAssetClass[assetClass].totalPnL += pnl;

  // By Grade
  if (aggregations.byGrade[gradeKey]) {
    aggregations.byGrade[gradeKey].push(trade);
  }

  // Track weaknesses
  if (trade.weaknesses && Array.isArray(trade.weaknesses)) {
    trade.weaknesses.forEach(w => {
      if (!aggregations.byWeakness[w]) aggregations.byWeakness[w] = { count: 0, trades: [] };
      aggregations.byWeakness[w].count++;
      aggregations.byWeakness[w].trades.push(trade.id || trade.tradeId);
    });
  }

  // Track lessons
  if (trade.lessons && Array.isArray(trade.lessons)) {
    trade.lessons.forEach(l => {
      if (!aggregations.byLesson[l]) aggregations.byLesson[l] = { count: 0, strategies: new Set(), firstSeen: trade.entry_time };
      aggregations.byLesson[l].count++;
      aggregations.byLesson[l].strategies.add(strategy);
    });
  }
});

// Process patterns from SC01
patterns.forEach(pattern => {
  const patternKey = pattern.dimension + ':' + pattern.key;
  if (!aggregations.byPatternType[patternKey]) {
    aggregations.byPatternType[patternKey] = { occurrences: 0, significance: [], recommendations: [] };
  }
  aggregations.byPatternType[patternKey].occurrences++;
  if (pattern.significance) aggregations.byPatternType[patternKey].significance.push(pattern.significance);
  if (pattern.recommendation) aggregations.byPatternType[patternKey].recommendations.push(pattern.recommendation);
});

// Calculate averages and rates
Object.values(aggregations.byTimeOfDay).forEach(cat => {
  if (cat.trades.length > 0) {
    const scores = cat.trades.map(t => gradeToScore[t.grade] || gradeToScore[t.grade?.charAt(0)] || 73);
    cat.avgGrade = scores.reduce((a, b) => a + b, 0) / scores.length;
  }
});

Object.values(aggregations.byAssetClass).forEach(cat => {
  if (cat.trades.length > 0) {
    const scores = cat.trades.map(t => gradeToScore[t.grade] || gradeToScore[t.grade?.charAt(0)] || 73);
    cat.avgGrade = scores.reduce((a, b) => a + b, 0) / scores.length;
    cat.winRate = cat.trades.filter(t => (parseFloat(t.pnl) || 0) > 0).length / cat.trades.length * 100;
  }
});

Object.values(aggregations.byStrategy).forEach(strat => {
  if (strat.grades.length > 0) {
    strat.avgGrade = strat.grades.reduce((a, b) => a + b, 0) / strat.grades.length;
    strat.winRate = strat.trades.filter(t => (parseFloat(t.pnl) || 0) > 0).length / strat.trades.length * 100;
  }
});

// Convert lesson sets to arrays
Object.values(aggregations.byLesson).forEach(l => {
  l.strategies = Array.from(l.strategies);
});

// Find recurring lessons (appeared in previous weeks)
const recurringLessons = [];
Object.entries(aggregations.byLesson).forEach(([lesson, data]) => {
  const previousMatch = previousLessons.find(pl => 
    pl.lesson?.toLowerCase().includes(lesson.toLowerCase().substring(0, 30)) ||
    lesson.toLowerCase().includes(pl.lesson?.toLowerCase().substring(0, 30) || '')
  );
  if (previousMatch) {
    recurringLessons.push({
      lesson: lesson,
      thisWeekCount: data.count,
      previousOccurrences: previousMatch.occurrences || 1,
      firstSeen: previousMatch.firstSeen || data.firstSeen,
      weeksRecurring: Math.ceil((Date.now() - new Date(previousMatch.firstSeen || data.firstSeen).getTime()) / (7 * 24 * 60 * 60 * 1000))
    });
  }
});

// Build summary statistics
const summary = {
  weekNumber: weekBounds.weekNumber,
  year: weekBounds.year,
  totalTrades: trades.length,
  totalPnL: trades.reduce((sum, t) => sum + (parseFloat(t.pnl) || 0), 0),
  avgGrade: trades.length > 0 ? trades.reduce((sum, t) => sum + (gradeToScore[t.grade] || gradeToScore[t.grade?.charAt(0)] || 73), 0) / trades.length : 0,
  winRate: trades.length > 0 ? trades.filter(t => (parseFloat(t.pnl) || 0) > 0).length / trades.length * 100 : 0,
  jiraTicketsCreated: jiraIssues.length,
  patternsDetected: patterns.length,
  activeHypotheses: hypotheses.length,
  uniqueWeaknesses: Object.keys(aggregations.byWeakness).length,
  uniqueLessons: Object.keys(aggregations.byLesson).length,
  recurringLessonsCount: recurringLessons.length
};

// Identify worst performing areas
const worstTimeOfDay = Object.entries(aggregations.byTimeOfDay)
  .filter(([_, data]) => data.trades.length >= 3)
  .sort((a, b) => a[1].avgGrade - b[1].avgGrade)[0];

const worstAssetClass = Object.entries(aggregations.byAssetClass)
  .filter(([_, data]) => data.trades.length >= 3)
  .sort((a, b) => a[1].avgGrade - b[1].avgGrade)[0];

const worstStrategy = Object.entries(aggregations.byStrategy)
  .filter(([_, data]) => data.trades.length >= 2)
  .sort((a, b) => a[1].avgGrade - b[1].avgGrade)[0];

const topWeaknesses = Object.entries(aggregations.byWeakness)
  .sort((a, b) => b[1].count - a[1].count)
  .slice(0, 5);

return {
  json: {
    summary,
    aggregations,
    insights: {
      worstTimeOfDay: worstTimeOfDay ? { time: worstTimeOfDay[0], avgGrade: worstTimeOfDay[1].avgGrade, tradeCount: worstTimeOfDay[1].trades.length } : null,
      worstAssetClass: worstAssetClass ? { class: worstAssetClass[0], avgGrade: worstAssetClass[1].avgGrade, tradeCount: worstAssetClass[1].trades.length } : null,
      worstStrategy: worstStrategy ? { strategy: worstStrategy[0], avgGrade: worstStrategy[1].avgGrade, tradeCount: worstStrategy[1].trades.length } : null,
      topWeaknesses: topWeaknesses.map(([w, d]) => ({ weakness: w, count: d.count })),
      recurringLessons
    },
    jiraIssues: jiraIssues.map(i => ({ key: i.key, summary: i.fields?.summary, labels: i.fields?.labels })),
    patterns: patterns,
    hypotheses: hypotheses,
    previousLessons: previousLessons.slice(0, 20)
  }
};

const data = $json;

const prompt = `You are the Chief Learning Officer for SwjshAK autonomous trading system. Your job is to synthesize weekly trading lessons into actionable insights.

## WEEK ${data.summary.weekNumber} SUMMARY (${data.summary.year})

### TRADING PERFORMANCE
- Total Trades: ${data.summary.totalTrades}
- Total P&L: $${data.summary.totalPnL.toFixed(2)}
- Average Grade: ${data.summary.avgGrade.toFixed(1)}/100
- Win Rate: ${data.summary.winRate.toFixed(1)}%

### JIRA LEARN TICKETS CREATED: ${data.summary.jiraTicketsCreated}
${data.jiraIssues.slice(0, 10).map(i => `- ${i.key}: ${i.summary}`).join('\n')}

### PATTERNS DETECTED THIS WEEK: ${data.summary.patternsDetected}
${Object.entries(data.aggregations.byPatternType).slice(0, 5).map(([k, v]) => `- ${k}: ${v.occurrences} occurrences`).join('\n')}

### PERFORMANCE BY STRATEGY
${Object.entries(data.aggregations.byStrategy).map(([s, d]) => `- ${s}: ${d.trades.length} trades, avg grade ${d.avgGrade?.toFixed(1) || 'N/A'}, $${d.totalPnL.toFixed(2)} P&L, ${d.winRate?.toFixed(1) || 0}% win rate`).join('\n')}

### PERFORMANCE BY TIME OF DAY
${Object.entries(data.aggregations.byTimeOfDay).filter(([_, d]) => d.trades.length > 0).map(([t, d]) => `- ${t}: ${d.trades.length} trades, avg grade ${d.avgGrade?.toFixed(1) || 'N/A'}, $${d.totalPnL.toFixed(2)} P&L`).join('\n')}

### PERFORMANCE BY ASSET CLASS
${Object.entries(data.aggregations.byAssetClass).filter(([_, d]) => d.trades.length > 0).map(([c, d]) => `- ${c}: ${d.trades.length} trades, avg grade ${d.avgGrade?.toFixed(1) || 'N/A'}, $${d.totalPnL.toFixed(2)} P&L, ${d.winRate?.toFixed(1) || 0}% win rate`).join('\n')}

### TOP WEAKNESSES IDENTIFIED
${data.insights.topWeaknesses.map(w => `- "${w.weakness}": ${w.count} occurrences`).join('\n')}

### RECURRING LESSONS (NOT LEARNING!)
${data.insights.recurringLessons.map(l => `- "${l.lesson.substring(0, 60)}...": ${l.weeksRecurring} weeks recurring, ${l.thisWeekCount} this week`).join('\n') || 'None detected - good job!'}

### ACTIVE HYPOTHESES BEING TRACKED: ${data.hypotheses.length}
${data.hypotheses.slice(0, 5).map(h => `- ${h.patternKey}: ${h.hypothesis?.substring(0, 50) || 'No description'}...`).join('\n')}

---

## YOUR TASK

Synthesize this data into a weekly learning report. Provide JSON:

{
  "weekSummary": "2-3 sentence high-level summary of the week's trading and lessons",
  "topInsights": [
    {
      "category": "strategy|timing|asset|pattern|psychological",
      "insight": "Clear, actionable insight statement",
      "evidence": "Data points supporting this insight",
      "priority": "high|medium|low",
      "actionRequired": "Specific action to take"
    }
  ],
  "strategiesNeedingWork": [
    {
      "strategy": "name",
      "issue": "what's wrong",
      "suggestedFix": "how to address"
    }
  ],
  "worstPerformingArea": {
    "area": "time/asset/strategy name",
    "type": "time_of_day|asset_class|strategy",
    "recommendation": "what to do about it"
  },
  "recurringMistakes": [
    {
      "mistake": "description",
      "weeksRecurring": number,
      "rootCause": "hypothesized root cause",
      "breakingAction": "specific action to break the pattern"
    }
  ],
  "winningPatterns": [
    "Things that worked well this week"
  ],
  "nextWeekFocus": [
    "Top 3 priorities for next week"
  ],
  "learningScore": {
    "score": 0-100,
    "rationale": "Why this score - are we learning from mistakes?"
  },
  "brainFileUpdates": [
    {
      "section": "strategies|patterns|timing|psychology",
      "content": "What to add/update in the brain knowledge base"
    }
  ]
}

Be brutally honest. If we're repeating mistakes, call it out. If strategies are underperforming, flag them. The goal is continuous improvement.`;

return {
  json: {
    prompt: prompt,
    rawData: data
  }
};

const response = $json;
const rawData = $('Code: Build AI Synthesis Prompt').first().json.rawData;

let synthesis;

try {
  const content = response.content?.[0]?.text || '';
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  synthesis = jsonMatch ? JSON.parse(jsonMatch[0]) : { error: 'Could not parse AI response' };
} catch (e) {
  synthesis = {
    weekSummary: 'AI synthesis parsing failed - review raw data manually',
    topInsights: [{ category: 'error', insight: 'Parsing failed: ' + e.message, evidence: 'N/A', priority: 'high', actionRequired: 'Manual review' }],
    strategiesNeedingWork: [],
    worstPerformingArea: null,
    recurringMistakes: [],
    winningPatterns: [],
    nextWeekFocus: ['Fix AI parsing', 'Review raw data', 'Manual lesson extraction'],
    learningScore: { score: 50, rationale: 'Could not properly analyze due to parsing error' },
    brainFileUpdates: [],
    _parseError: e.message
  };
}

// Add metadata
synthesis.metadata = {
  weekNumber: rawData.summary.weekNumber,
  year: rawData.summary.year,
  generatedAt: new Date().toISOString(),
  totalTrades: rawData.summary.totalTrades,
  totalPnL: rawData.summary.totalPnL
};

// Add raw summary for reference
synthesis.rawSummary = rawData.summary;
synthesis.rawInsights = rawData.insights;

return { json: synthesis };

const synthesis = $json;

// Format lessons for brain file
const lessonsMarkdown = `# Weekly Lessons - Week ${synthesis.metadata.weekNumber} (${synthesis.metadata.year})

> Generated: ${synthesis.metadata.generatedAt}
> Trades: ${synthesis.metadata.totalTrades} | P&L: $${synthesis.metadata.totalPnL?.toFixed(2) || '0.00'}

## Summary
${synthesis.weekSummary}

## Learning Score: ${synthesis.learningScore?.score || 'N/A'}/100
${synthesis.learningScore?.rationale || ''}

## Top Insights
${(synthesis.topInsights || []).map((i, idx) => `
### ${idx + 1}. [${i.priority?.toUpperCase() || 'MEDIUM'}] ${i.category}
**Insight:** ${i.insight}
**Evidence:** ${i.evidence}
**Action:** ${i.actionRequired}
`).join('')}

## Strategies Needing Work
${(synthesis.strategiesNeedingWork || []).map(s => `- **${s.strategy}**: ${s.issue} - *Fix: ${s.suggestedFix}*`).join('\n') || 'None identified'}

## Recurring Mistakes (STOP REPEATING!)
${(synthesis.recurringMistakes || []).map(m => `
### ${m.mistake}
- Recurring for: ${m.weeksRecurring} weeks
- Root cause: ${m.rootCause}
- **Break it:** ${m.breakingAction}
`).join('') || 'No recurring mistakes - excellent!'}

## What Worked Well
${(synthesis.winningPatterns || []).map(w => `- ${w}`).join('\n') || 'Need more data to identify patterns'}

## Next Week Focus
${(synthesis.nextWeekFocus || []).map((f, i) => `${i + 1}. ${f}`).join('\n')}

---
*Auto-generated by WF-LEARN-01 Lesson Compiler*
`;

return {
  json: {
    synthesis,
    lessonsMarkdown,
    brainUpdates: synthesis.brainFileUpdates || [],
    fileName: `lessons-week-${synthesis.metadata.weekNumber}-${synthesis.metadata.year}.md`
  }
};

