const formatData = $('Code: Format Brain Updates').first().json;
const synthesis = formatData.synthesis;

// Determine embed color based on learning score
let embedColor = 3066993; // Green
if (synthesis.learningScore?.score < 50) {
  embedColor = 15158332; // Red
} else if (synthesis.learningScore?.score < 70) {
  embedColor = 16776960; // Yellow
}

// Build fields for embed
const fields = [
  {
    name: ':chart_with_upwards_trend: P&L',
    value: `$${synthesis.metadata?.totalPnL?.toFixed(2) || '0.00'}`,
    inline: true
  },
  {
    name: ':1234: Trades',
    value: `${synthesis.metadata?.totalTrades || 0}`,
    inline: true
  },
  {
    name: ':brain: Learning Score',
    value: `${synthesis.learningScore?.score || 'N/A'}/100`,
    inline: true
  }
];

// Add top insights
if (synthesis.topInsights?.length > 0) {
  const insightText = synthesis.topInsights.slice(0, 3)
    .map((i, idx) => `${idx + 1}. **[${i.priority}]** ${i.insight.substring(0, 100)}`)
    .join('\n');
  fields.push({
    name: ':bulb: Top Insights',
    value: insightText || 'None',
    inline: false
  });
}

// Add strategies needing work
if (synthesis.strategiesNeedingWork?.length > 0) {
  fields.push({
    name: ':warning: Strategies Needing Work',
    value: synthesis.strategiesNeedingWork.slice(0, 3).map(s => `- ${s.strategy}`).join('\n'),
    inline: true
  });
}

// Add recurring mistakes if any
if (synthesis.recurringMistakes?.length > 0) {
  fields.push({
    name: ':rotating_light: Recurring Mistakes',
    value: synthesis.recurringMistakes.slice(0, 2).map(m => `- ${m.mistake.substring(0, 50)}... (${m.weeksRecurring}w)`).join('\n'),
    inline: true
  });
}

// Add next week focus
if (synthesis.nextWeekFocus?.length > 0) {
  fields.push({
    name: ':dart: Next Week Focus',
    value: synthesis.nextWeekFocus.map((f, i) => `${i + 1}. ${f.substring(0, 80)}`).join('\n'),
    inline: false
  });
}

const embed = {
  title: `:book: Weekly Learning Report - Week ${synthesis.metadata?.weekNumber || '?'}`,
  description: synthesis.weekSummary?.substring(0, 500) || 'Weekly lesson compilation complete.',
  color: embedColor,
  fields: fields,
  footer: {
    text: `SwjshAK Learning System | Score: ${synthesis.learningScore?.score || 'N/A'}/100`
  },
  timestamp: new Date().toISOString()
};

return {
  json: {
    embed,
    synthesis,
    channelId: process.env.DISCORD_CEO_CHANNEL_ID || 'ceo-briefing'
  }
};

const synthesis = $('Code: Format Discord Report').first().json.synthesis;
const recurringMistakes = synthesis.recurringMistakes || [];

// Only escalate mistakes recurring 3+ weeks
const escalatableItems = recurringMistakes
  .filter(m => m.weeksRecurring >= 3)
  .map(m => ({
    json: {
      mistake: m.mistake,
      weeksRecurring: m.weeksRecurring,
      rootCause: m.rootCause,
      breakingAction: m.breakingAction,
      weekNumber: synthesis.metadata?.weekNumber,
      year: synthesis.metadata?.year
    }
  }));

return escalatableItems.length > 0 ? escalatableItems : [{ json: { skip: true } }];

const data = $json;

return {
  json: {
    synthesis: {
      weekSummary: `Week ${data.summary?.weekNumber || '?'} had insufficient trading data (${data.summary?.totalTrades || 0} trades). Minimum 5 trades required for meaningful analysis.`,
      topInsights: [{
        category: 'data',
        insight: 'Insufficient trading volume for pattern analysis',
        evidence: `Only ${data.summary?.totalTrades || 0} trades this week`,
        priority: 'low',
        actionRequired: 'Continue trading to build data set'
      }],
      strategiesNeedingWork: [],
      worstPerformingArea: null,
      recurringMistakes: [],
      winningPatterns: [],
      nextWeekFocus: ['Increase trading activity', 'Focus on quality setups', 'Build data for analysis'],
      learningScore: { score: 50, rationale: 'Insufficient data to assess learning progress' },
      brainFileUpdates: [],
      metadata: {
        weekNumber: data.summary?.weekNumber || 0,
        year: data.summary?.year || 2026,
        generatedAt: new Date().toISOString(),
        totalTrades: data.summary?.totalTrades || 0,
        totalPnL: data.summary?.totalPnL || 0
      }
    },
    rawSummary: data.summary,
    isMinimalReport: true
  }
};

const error = $json;

const errorEmbed = {
  title: ':warning: Weekly Lesson Compiler Error',
  description: 'WF-LEARN-01 encountered an error during weekly lesson compilation.',
  color: 15158332,
  fields: [
    {
      name: 'Error Message',
      value: error.execution?.error?.message?.substring(0, 1000) || 'Unknown error',
      inline: false
    },
    {
      name: 'Failed Node',
      value: error.execution?.error?.node?.name || 'Unknown',
      inline: true
    },
    {
      name: 'Execution ID',
      value: error.execution?.id || 'Unknown',
      inline: true
    }
  ],
  footer: {
    text: 'WF-LEARN-01 Error Handler'
  },
  timestamp: new Date().toISOString()
};

return { json: { embed: errorEmbed } };
